"""Apollo.io Organization Enrichment Tool.

Enriches company/organization data using the Apollo.io API.
Provide a domain, company name, or LinkedIn URL to get company details.

API Reference: https://docs.apollo.io/reference/organization-enrichment
Endpoint: GET https://api.apollo.io/api/v1/organizations/enrich
Auth: x-api-key header
"""

import json
from typing import Any, cast

import requests
from langchain_core.tools import StructuredTool

from lfx.base.langchain_utilities.model import LCToolComponent
from lfx.field_typing import Tool
from lfx.inputs.inputs import MessageTextInput, SecretStrInput
from lfx.schema.data import Data


class ApolloOrgEnrichmentComponent(LCToolComponent):
    """Enrich company data using Apollo.io — get industry, size, funding, tech stack, and more.

    Provide a domain, company name, or LinkedIn URL to look up detailed
    organization information. Connect this tool to any GTM agent.
    """

    display_name = "Apollo Organization Enrichment"
    description = (
        "Enrich company data via Apollo.io API. Returns industry, employee count, "
        "funding, technologies, location, and more."
    )
    icon = "Apollo"
    name = "ApolloOrgEnrichment"

    inputs = [
        SecretStrInput(
            name="api_key",
            display_name="Apollo API Key",
            info="Your Apollo.io API key from Settings > Integrations > API Keys.",
            required=True,
        ),
        MessageTextInput(
            name="input_value",
            display_name="Company Lookup",
            info=(
                "Company domain (e.g., 'stripe.com'), company name, or LinkedIn company URL. "
                "When used as a tool, the agent will pass this automatically."
            ),
            tool_mode=True,
        ),
        MessageTextInput(
            name="domain",
            display_name="Company Domain",
            info="Company domain (e.g., 'stripe.com'). Do not include 'www.' or '@'.",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="organization_name",
            display_name="Organization Name",
            info="Company name to look up.",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="linkedin_url",
            display_name="LinkedIn Company URL",
            info="Company LinkedIn profile URL.",
            required=False,
            advanced=True,
        ),
    ]

    API_URL = "https://api.apollo.io/api/v1/organizations/enrich"

    def _build_request_params(self) -> dict[str, str]:
        """Build request parameters from component inputs."""
        params: dict[str, str] = {}

        if getattr(self, "domain", None):
            params["domain"] = self.domain
        if getattr(self, "organization_name", None):
            params["organization_name"] = self.organization_name
        if getattr(self, "linkedin_url", None):
            params["linkedin_url"] = self.linkedin_url

        return params

    def _parse_query_string(self, query: str) -> dict[str, str]:
        """Parse a query into API parameters."""
        query = query.strip()

        if "linkedin.com" in query:
            return {"linkedin_url": query}

        # If it looks like a domain (contains a dot, no spaces)
        if "." in query and " " not in query:
            return {"domain": query.replace("www.", "").replace("https://", "").replace("http://", "").split("/")[0]}

        return {"organization_name": query}

    def _enrich_org(self, api_key: str, params: dict[str, str]) -> dict[str, Any]:
        """Call Apollo Organization Enrichment API."""
        headers = {
            "Content-Type": "application/json",
            "Cache-Control": "no-cache",
            "x-api-key": api_key,
        }

        response = requests.get(self.API_URL, headers=headers, params=params, timeout=30)

        if response.status_code == 429:
            return {"error": "Rate limit exceeded. Please wait and try again.", "status": 429}
        if response.status_code == 401:
            return {"error": "Invalid API key. Check your Apollo API key.", "status": 401}

        response.raise_for_status()
        return response.json()

    def _format_org_result(self, data: dict[str, Any]) -> str:
        """Format organization enrichment result into readable text."""
        org = data.get("organization")
        if not org:
            return "No organization data found for the given query."

        lines = []
        lines.append(f"**Company:** {org.get('name', 'N/A')}")
        lines.append(f"**Website:** {org.get('website_url', 'N/A')}")
        lines.append(f"**Industry:** {org.get('industry', 'N/A')}")
        lines.append(f"**Employees:** {org.get('estimated_num_employees', 'N/A')}")
        lines.append(f"**Founded:** {org.get('founded_year', 'N/A')}")
        lines.append(f"**Annual Revenue:** {org.get('annual_revenue', 'N/A')}")
        lines.append(f"**Total Funding:** {org.get('total_funding', 'N/A')}")
        lines.append(f"**Latest Funding Stage:** {org.get('latest_funding_stage', 'N/A')}")
        lines.append(f"**LinkedIn:** {org.get('linkedin_url', 'N/A')}")
        lines.append(
            f"**Location:** {org.get('city', '')}, {org.get('state', '')}, {org.get('country', '')}"
        )
        lines.append(f"**Phone:** {org.get('phone', 'N/A')}")

        technologies = org.get("technologies", [])
        if technologies:
            lines.append(f"\n**Technologies:** {', '.join(technologies[:20])}")
            if len(technologies) > 20:
                lines.append(f"  ... and {len(technologies) - 20} more")

        funding_events = org.get("funding_events", [])
        if funding_events:
            lines.append("\n**Funding Events:**")
            for event in funding_events[:5]:
                if isinstance(event, dict):
                    lines.append(
                        f"  - {event.get('type', 'N/A')}: ${event.get('amount', 'N/A')} "
                        f"({event.get('date', 'N/A')})"
                    )

        return "\n".join(lines)

    def run_model(self) -> list[Data]:
        """Run organization enrichment with the configured inputs."""
        params = self._build_request_params()

        if not params and getattr(self, "input_value", None):
            params = self._parse_query_string(self.input_value)

        if not params:
            return [Data(text="No lookup parameters provided. Provide a domain, company name, or LinkedIn URL.")]

        result = self._enrich_org(self.api_key, params)

        if "error" in result:
            return [Data(text=f"Apollo API Error: {result['error']}", data=result)]

        formatted = self._format_org_result(result)
        data = [Data(text=formatted, data=result)]
        self.status = data
        return data

    def build_tool(self) -> Tool:
        """Build a LangChain tool for agent use."""
        api_key = self.api_key

        def enrich_organization(
            query: str = "",
            domain: str = "",
            organization_name: str = "",
            linkedin_url: str = "",
        ) -> str:
            """Enrich company data using Apollo.io. Provide domain, company name, or LinkedIn URL.

            Args:
                query: Company domain like 'stripe.com', company name, or LinkedIn URL
                domain: Company domain (e.g., 'stripe.com')
                organization_name: Company name
                linkedin_url: Company LinkedIn URL
            """
            params: dict[str, str] = {}

            if domain:
                params["domain"] = domain
            if organization_name:
                params["organization_name"] = organization_name
            if linkedin_url:
                params["linkedin_url"] = linkedin_url

            if not params and query:
                params = self._parse_query_string(query)

            if not params:
                return "No parameters provided. Provide a domain, company name, or LinkedIn URL."

            result = self._enrich_org(api_key, params)

            if "error" in result:
                return f"Apollo API Error: {result['error']}"

            return self._format_org_result(result)

        return cast(
            "Tool",
            StructuredTool.from_function(
                func=enrich_organization,
                name="apollo_org_enrichment",
                description=(
                    "Look up detailed company information using Apollo.io. "
                    "Returns industry, employee count, funding, technologies, location. "
                    "Best for: Company Firmographics, Funding Events, Company Growth Stage, Market Category Fit."
                ),
            ),
        )

"""Hunter.io Email Finder Tool.

Find the email address of a specific person by providing their name and company domain.

API Reference: https://hunter.io/api-documentation/v2
Endpoint: GET https://api.hunter.io/v2/email-finder
Auth: api_key query parameter or X-API-KEY header
Rate Limit: 15 req/sec, 500 req/min
"""

import json
from typing import Any, cast

import requests
from langchain_core.tools import StructuredTool

from lfx.base.langchain_utilities.model import LCToolComponent
from lfx.field_typing import Tool
from lfx.inputs.inputs import MessageTextInput, SecretStrInput
from lfx.schema.data import Data


class HunterEmailFinderComponent(LCToolComponent):
    """Find a person's email using Hunter.io — provide name + domain to get their email.

    Uses Hunter.io's Email Finder API to discover the most likely email address
    for a specific person at a company.
    """

    display_name = "Hunter Email Finder"
    description = (
        "Find a person's email address using Hunter.io. Provide first name, "
        "last name, and company domain to get their email with confidence score."
    )
    icon = "Hunter"
    name = "HunterEmailFinder"

    inputs = [
        SecretStrInput(
            name="api_key",
            display_name="Hunter API Key",
            info="Your Hunter.io API key.",
            required=True,
        ),
        MessageTextInput(
            name="input_value",
            display_name="Lookup Query",
            info=(
                "Person lookup: 'First Last at domain.com' or 'First Last @ company.com'. "
                "When used as a tool, the agent passes this automatically."
            ),
            tool_mode=True,
        ),
        MessageTextInput(
            name="first_name",
            display_name="First Name",
            info="Person's first name.",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="last_name",
            display_name="Last Name",
            info="Person's last name.",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="domain",
            display_name="Company Domain",
            info="Company domain (e.g., 'stripe.com').",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="company",
            display_name="Company Name",
            info="Company name (alternative to domain).",
            required=False,
            advanced=True,
        ),
    ]

    API_URL = "https://api.hunter.io/v2/email-finder"

    def _parse_query_string(self, query: str) -> dict[str, str]:
        """Parse a natural-language query into API parameters."""
        query = query.strip()
        parts = query.replace(" at ", " @ ").split("@")

        if len(parts) == 2:
            name_part = parts[0].strip()
            domain_part = parts[1].strip()
            name_parts = name_part.split()

            result: dict[str, str] = {}
            if len(name_parts) >= 2:
                result["first_name"] = name_parts[0]
                result["last_name"] = " ".join(name_parts[1:])
            elif len(name_parts) == 1:
                result["full_name"] = name_parts[0]

            # Determine if domain_part is a domain or company name
            clean = domain_part.replace("www.", "").replace("https://", "").replace("http://", "")
            if "." in clean and " " not in clean:
                result["domain"] = clean
            else:
                result["company"] = domain_part

            return result

        return {"full_name": query}

    def _find_email(self, api_key: str, params: dict[str, str]) -> dict[str, Any]:
        """Call Hunter.io Email Finder API."""
        params["api_key"] = api_key

        response = requests.get(self.API_URL, params=params, timeout=30)

        if response.status_code == 429:
            return {"error": "Monthly quota exceeded. Upgrade your Hunter.io plan.", "status": 429}
        if response.status_code == 401:
            return {"error": "Invalid API key. Check your Hunter.io API key.", "status": 401}
        if response.status_code == 403:
            return {"error": "Rate limit exceeded. Please wait and try again.", "status": 403}
        if response.status_code == 451:
            return {"error": "This person has requested their data not be processed (GDPR).", "status": 451}

        response.raise_for_status()
        return response.json()

    def _format_result(self, data: dict[str, Any]) -> str:
        """Format email finder result into readable text."""
        result = data.get("data", {})
        if not result or not result.get("email"):
            return "No email found for the given person and domain."

        lines = []
        lines.append(f"**Email Found:** {result.get('email', 'N/A')}")
        lines.append(f"**Confidence Score:** {result.get('score', 'N/A')}%")
        lines.append(f"**Name:** {result.get('first_name', '')} {result.get('last_name', '')}")
        lines.append(f"**Position:** {result.get('position', 'N/A')}")
        lines.append(f"**Company:** {result.get('company', 'N/A')}")
        lines.append(f"**Domain:** {result.get('domain', 'N/A')}")
        lines.append(f"**Accept All:** {result.get('accept_all', 'N/A')}")

        verification = result.get("verification", {})
        if isinstance(verification, dict):
            lines.append(f"**Verification Status:** {verification.get('status', 'N/A')}")
            lines.append(f"**Verification Date:** {verification.get('date', 'N/A')}")

        sources = result.get("sources", [])
        if sources:
            lines.append(f"\n**Sources ({len(sources)}):**")
            for source in sources[:5]:
                if isinstance(source, dict):
                    lines.append(f"  - {source.get('uri', source.get('domain', 'N/A'))}")

        return "\n".join(lines)

    def run_model(self) -> list[Data]:
        """Run email finder with the configured inputs."""
        params: dict[str, str] = {}

        if getattr(self, "first_name", None):
            params["first_name"] = self.first_name
        if getattr(self, "last_name", None):
            params["last_name"] = self.last_name
        if getattr(self, "domain", None):
            params["domain"] = self.domain
        if getattr(self, "company", None):
            params["company"] = self.company

        if not params and getattr(self, "input_value", None):
            params = self._parse_query_string(self.input_value)

        if not params:
            return [Data(text="No parameters provided. Provide name + domain or company.")]

        result = self._find_email(self.api_key, params)

        if "error" in result:
            return [Data(text=f"Hunter API Error: {result['error']}", data=result)]

        formatted = self._format_result(result)
        data = [Data(text=formatted, data=result)]
        self.status = data
        return data

    def build_tool(self) -> Tool:
        """Build a LangChain tool for agent use."""
        api_key = self.api_key

        def find_email(
            query: str = "",
            first_name: str = "",
            last_name: str = "",
            domain: str = "",
            company: str = "",
        ) -> str:
            """Find a person's email address using Hunter.io. Provide name + company domain.

            Args:
                query: Natural language like 'John Doe at stripe.com'
                first_name: Person's first name
                last_name: Person's last name
                domain: Company domain (e.g., 'stripe.com')
                company: Company name (alternative to domain)
            """
            params: dict[str, str] = {}

            if first_name:
                params["first_name"] = first_name
            if last_name:
                params["last_name"] = last_name
            if domain:
                params["domain"] = domain
            if company:
                params["company"] = company

            if not params and query:
                params = self._parse_query_string(query)

            if not params:
                return "No parameters provided. Provide name + domain or company."

            result = self._find_email(api_key, params)

            if "error" in result:
                return f"Hunter API Error: {result['error']}"

            return self._format_result(result)

        return cast(
            "Tool",
            StructuredTool.from_function(
                func=find_email,
                name="hunter_email_finder",
                description=(
                    "Find a specific person's email address using Hunter.io. "
                    "Provide first name + last name + company domain to discover their email. "
                    "Best for: Contact Availability, Email Quality Signals."
                ),
            ),
        )

"""People Data Labs Company Enrichment Tool.

Enriches company data using the PDL API. Provide a domain, company name,
ticker, or LinkedIn URL to get detailed company information.

API Reference: https://docs.peopledatalabs.com/docs/reference-company-enrichment-api
Endpoint: GET https://api.peopledatalabs.com/v5/company/enrich
Auth: X-Api-Key header
"""

import json
from typing import Any, cast

import requests
from langchain_core.tools import StructuredTool

from lfx.base.langchain_utilities.model import LCToolComponent
from lfx.field_typing import Tool
from lfx.inputs.inputs import MessageTextInput, SecretStrInput
from lfx.schema.data import Data


class PDLCompanyEnrichmentComponent(LCToolComponent):
    """Enrich company data using People Data Labs — employee trends, funding, industry, and growth signals.

    Provide a domain, company name, ticker symbol, or LinkedIn URL to get detailed
    company information including size, funding, employee growth, and hiring trends.
    """

    display_name = "PDL Company Enrichment"
    description = (
        "Enrich company data via People Data Labs API. Returns industry, employee count, "
        "funding, growth rate, employee churn, recent exec hires/departures, and more."
    )
    icon = "PDL"
    name = "PDLCompanyEnrichment"

    inputs = [
        SecretStrInput(
            name="api_key",
            display_name="PDL API Key",
            info="Your People Data Labs API key.",
            required=True,
        ),
        MessageTextInput(
            name="input_value",
            display_name="Company Lookup",
            info=(
                "Company domain (e.g., 'stripe.com'), company name, ticker symbol, or LinkedIn URL. "
                "When used as a tool, the agent passes this automatically."
            ),
            tool_mode=True,
        ),
        MessageTextInput(
            name="website",
            display_name="Website / Domain",
            info="Company website or domain (e.g., 'stripe.com').",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="name",
            display_name="Company Name",
            info="Company name to look up.",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="ticker",
            display_name="Ticker Symbol",
            info="Stock ticker symbol (e.g., 'AAPL').",
            required=False,
            advanced=True,
        ),
        MessageTextInput(
            name="profile",
            display_name="LinkedIn Company URL",
            info="Company LinkedIn profile URL.",
            required=False,
            advanced=True,
        ),
    ]

    API_URL = "https://api.peopledatalabs.com/v5/company/enrich"

    def _build_request_params(self) -> dict[str, str]:
        """Build request parameters from component inputs."""
        params: dict[str, str] = {}

        if getattr(self, "website", None):
            params["website"] = self.website
        if getattr(self, "name", None):
            params["name"] = self.name
        if getattr(self, "ticker", None):
            params["ticker"] = self.ticker
        if getattr(self, "profile", None):
            params["profile"] = self.profile

        return params

    def _parse_query_string(self, query: str) -> dict[str, str]:
        """Parse a query into API parameters."""
        query = query.strip()

        if "linkedin.com" in query:
            return {"profile": query}

        # If it looks like a ticker (all caps, 1-5 chars)
        if query.isupper() and 1 <= len(query) <= 5 and query.isalpha():
            return {"ticker": query}

        # If it looks like a domain (contains a dot, no spaces)
        if "." in query and " " not in query:
            clean = query.replace("www.", "").replace("https://", "").replace("http://", "").split("/")[0]
            return {"website": clean}

        return {"name": query}

    def _enrich_company(self, api_key: str, params: dict[str, str]) -> dict[str, Any]:
        """Call PDL Company Enrichment API."""
        headers = {
            "X-Api-Key": api_key,
            "Content-Type": "application/json",
        }

        response = requests.get(self.API_URL, headers=headers, params=params, timeout=30)

        if response.status_code == 404:
            return {"error": "No matching company found.", "status": 404}
        if response.status_code == 429:
            return {"error": "Rate limit exceeded. Please wait and try again.", "status": 429}
        if response.status_code == 401:
            return {"error": "Invalid API key. Check your PDL API key.", "status": 401}
        if response.status_code == 402:
            return {"error": "Credit limit reached. Check your PDL account usage.", "status": 402}

        response.raise_for_status()
        return response.json()

    def _format_company_result(self, data: dict[str, Any]) -> str:
        """Format company enrichment result.

        Note: PDL Company Enrichment returns fields at the ROOT level, not nested under 'data'.
        """
        # PDL returns company fields at the root level
        company = data
        likelihood = data.get("likelihood", "N/A")

        lines = []
        lines.append(f"**Confidence:** {likelihood}/10")
        lines.append(f"**Company:** {company.get('display_name', company.get('name', 'N/A'))}")
        lines.append(f"**Website:** {company.get('website', 'N/A')}")
        lines.append(f"**Industry:** {company.get('industry', 'N/A')}")
        lines.append(f"**Type:** {company.get('type', 'N/A')}")
        lines.append(f"**Employees:** {company.get('employee_count', 'N/A')}")
        lines.append(f"**Size Range:** {company.get('size', 'N/A')}")
        lines.append(f"**Founded:** {company.get('founded', 'N/A')}")
        lines.append(f"**Total Funding:** {company.get('total_funding_raised', 'N/A')}")
        lines.append(f"**Latest Funding Stage:** {company.get('latest_funding_stage', 'N/A')}")
        lines.append(f"**Inferred Revenue:** {company.get('inferred_revenue', 'N/A')}")

        location = company.get("location", {})
        if isinstance(location, dict):
            lines.append(f"**Location:** {location.get('name', 'N/A')}")

        lines.append(f"**LinkedIn:** {company.get('linkedin_url', 'N/A')}")
        lines.append(f"**Headline:** {company.get('headline', 'N/A')}")

        # Employee growth
        growth = company.get("employee_growth_rate", {})
        if isinstance(growth, dict) and any(growth.values()):
            lines.append("\n**Employee Growth Rate:**")
            for period in ["3_month", "6_month", "12_month", "24_month"]:
                val = growth.get(period)
                if val is not None:
                    lines.append(f"  - {period.replace('_', ' ')}: {val:.1%}" if isinstance(val, float) else f"  - {period.replace('_', ' ')}: {val}")

        # Recent exec hires
        exec_hires = company.get("recent_exec_hires", [])
        if exec_hires:
            lines.append("\n**Recent Executive Hires:**")
            for hire in exec_hires[:5]:
                if isinstance(hire, dict):
                    lines.append(f"  - {hire.get('job_title', 'N/A')} (joined {hire.get('joined_date', 'N/A')})")

        # Recent exec departures
        exec_departures = company.get("recent_exec_departures", [])
        if exec_departures:
            lines.append("\n**Recent Executive Departures:**")
            for dep in exec_departures[:5]:
                if isinstance(dep, dict):
                    lines.append(f"  - {dep.get('job_title', 'N/A')} (departed {dep.get('departed_date', 'N/A')})")

        # Tags
        tags = company.get("tags", [])
        if tags:
            lines.append(f"\n**Tags:** {', '.join(tags[:15])}")

        return "\n".join(lines)

    def run_model(self) -> list[Data]:
        """Run company enrichment with the configured inputs."""
        params = self._build_request_params()

        if not params and getattr(self, "input_value", None):
            params = self._parse_query_string(self.input_value)

        if not params:
            return [Data(text="No lookup parameters provided. Provide a domain, company name, ticker, or LinkedIn URL.")]

        result = self._enrich_company(self.api_key, params)

        if "error" in result:
            return [Data(text=f"PDL API Error: {result['error']}", data=result)]

        formatted = self._format_company_result(result)
        data = [Data(text=formatted, data=result)]
        self.status = data
        return data

    def build_tool(self) -> Tool:
        """Build a LangChain tool for agent use."""
        api_key = self.api_key

        def enrich_company(
            query: str = "",
            website: str = "",
            name: str = "",
            ticker: str = "",
            linkedin_url: str = "",
        ) -> str:
            """Enrich company data using People Data Labs. Returns industry, size, funding, growth, exec hires.

            Args:
                query: Company domain like 'stripe.com', name, ticker symbol, or LinkedIn URL
                website: Company domain (e.g., 'stripe.com')
                name: Company name
                ticker: Stock ticker symbol (e.g., 'AAPL')
                linkedin_url: Company LinkedIn URL
            """
            params: dict[str, str] = {}

            if website:
                params["website"] = website
            if name:
                params["name"] = name
            if ticker:
                params["ticker"] = ticker
            if linkedin_url:
                params["profile"] = linkedin_url

            if not params and query:
                params = self._parse_query_string(query)

            if not params:
                return "No parameters provided. Provide a domain, company name, ticker, or LinkedIn URL."

            result = self._enrich_company(api_key, params)

            if "error" in result:
                return f"PDL API Error: {result['error']}"

            return self._format_company_result(result)

        return cast(
